code="""<script id="l3n-litetrace-fast-telemetry-3992">\n(()=>{\nconst V='3.99.2',state={last:null,history:[]};const finite=v=>Number.isFinite(Number(v))?Number(v):0;\nfunction fromJob(job){if(!job)return null;const ps=job.performance?.snapshot?.()||job.performance||{};const elapsedMs=finite(job.elapsedMs||ps.elapsedMs),cameraRays=finite(ps.cameraRays),pathRays=finite(ps.pathRays),shadowRays=finite(ps.shadowRays),probeRays=finite(ps.probeRays),totalRays=finite(ps.totalRays)||(cameraRays+pathRays+shadowRays+probeRays);return {version:V,renderer:'LiteTrace Fast',renderId:job.id??job.renderId??null,status:job.status??null,elapsedMs,currentSamples:finite(job.progress?.currentSamples||ps.samples),maximumSamples:finite(job.settings?.maxSamples||1),totalRays,primaryRays:cameraRays,secondaryRays:pathRays+probeRays,shadowRays,probeRays,reflectionRays:finite(ps.reflectionRays),refractionRays:finite(ps.refractionRays),raysPerSecond:finite(ps.raysPerSecond),stageMs:ps.stageMs?{...ps.stageMs}:null,engine:job.settings?.engine??'fast'};}\nfunction capture(job){const x=fromJob(job);if(!x)return null;state.last=x;state.history.push(x);if(state.history.length>32)state.history.splice(0,state.history.length-32);try{window.ThreeDLiteAdaptiveRender3990?.observe?.(x);}catch(_){}return {...x};}\nfunction bind(){const rf=window.RenderFramework;if(!rf)return false;if(rf.__liteTraceTelemetry3992)return true;rf.__liteTraceTelemetry3992=true;const done=rf.recordCompleted?.bind(rf);if(done)rf.recordCompleted=(job)=>{try{capture(job);}catch(e){console.warn('[LiteTrace Fast telemetry]',e);}return done(job);};return true;}\nwindow.ThreeDLiteLiteTraceFastTelemetry3992={version:V,capture,fromJob,getLast:()=>state.last?{...state.last}:null,getHistory:()=>state.history.map(x=>({...x})),reset:()=>{state.last=null;state.history.length=0;}};window.__3DLiteLiteTraceFastTelemetry3992=true;if(!bind())window.addEventListener('load',bind,{once:true});\n})();\n</script>\n"""
